pub fn description() -> String { format!("Veyra {}\n\nA file manager built with GPUI. Settings are saved to your XDG configuration directory under veyra/settings.json.\n\nCtrl+, opens Settings. Escape closes Settings. Ctrl+H toggles hidden files.\n\nSettings organization is inspired by Dux Files. System color integration, thumbnails, drag-and-drop, and device management are planned separately.", env!("CARGO_PKG_VERSION")) }
